import { ReportData } from "./reportTypes";
import { getGrade, calcHealthAge } from "./reportLogic";

// ═══════════════════════════════════════════════════════════════
//  AORANE HEALTH INTELLIGENCE REPORT — Premium v4.0
//  Condensed 4-page report: crisp, data-dense, professionally designed
//  Fixes: score ring cut-off, blank space, 10→4 pages, logo, data sync
// ═══════════════════════════════════════════════════════════════

// ── Logo base64 (embedded directly from assets/images/aorane-logo.png) ──
const LOGO_B64 = "";

function logoImg(h: number): string {
  return `<img src="data:image/png;base64,${LOGO_B64}" height="${h}" style="display:block;object-fit:contain" alt="Aorane"/>`;
}

// ─── Color Helpers ────────────────────────────────────────────

function scoreColor(s: number): string {
  if (s >= 90) return "#059669";
  if (s >= 76) return "#0EA5E9";
  if (s >= 61) return "#F59E0B";
  if (s >= 41) return "#F97316";
  return "#EF4444";
}

function getStatus(s: number): string {
  if (s >= 90) return "Excellent";
  if (s >= 76) return "Good";
  if (s >= 61) return "Fair";
  if (s >= 41) return "Below Average";
  return "Needs Attention";
}

function riskColor(r: "Low" | "Moderate" | "High"): string {
  if (r === "Low") return "#059669";
  if (r === "Moderate") return "#F59E0B";
  return "#EF4444";
}

function riskBg(r: "Low" | "Moderate" | "High"): string {
  if (r === "Low") return "#ECFDF5";
  if (r === "Moderate") return "#FFFBEB";
  return "#FEF2F2";
}

function pctColor(p: number): string {
  if (p >= 80) return "#059669";
  if (p >= 50) return "#F59E0B";
  return "#EF4444";
}

function fmtDate(d: Date | string | undefined): string {
  if (!d) return "—";
  try {
    return new Date(d).toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" });
  } catch { return "—"; }
}

function fmtDay(d: Date | string | undefined): string {
  if (!d) return "—";
  try {
    return new Date(d).toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric", weekday: "short" });
  } catch { return "—"; }
}

// ─── Score Ring (SVG, no clipping) ───────────────────────────
function scoreRing(score: number, size: number, label: string, sublabel: string, color: string): string {
  const r = 38;
  const circ = 2 * Math.PI * r;
  const dash = Math.max(0, Math.min((score / 100) * circ, circ));
  // Font sizes tuned so 2-digit & 3-digit scores both fit
  const scoreFontSize = score >= 100 ? 16 : 20;
  return `
    <svg width="${size}" height="${size}" viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
      <circle cx="50" cy="50" r="${r}" fill="none" stroke="#E8F0F8" stroke-width="9"/>
      <circle cx="50" cy="50" r="${r}" fill="none" stroke="${color}22" stroke-width="9"/>
      <circle cx="50" cy="50" r="${r}" fill="none" stroke="${color}" stroke-width="9"
        stroke-linecap="round"
        stroke-dasharray="${dash.toFixed(2)} ${circ.toFixed(2)}"
        transform="rotate(-90 50 50)"/>
      <text x="50" y="46" text-anchor="middle" font-size="${scoreFontSize}" font-weight="800"
        fill="${color}" font-family="'Segoe UI',Arial,sans-serif">${score}</text>
      <text x="50" y="57" text-anchor="middle" font-size="7" font-weight="600"
        fill="#94A3B8" font-family="Arial,sans-serif" letter-spacing="0.3">${label}</text>
      <text x="50" y="67" text-anchor="middle" font-size="7.5" font-weight="700"
        fill="${color}" font-family="Arial,sans-serif">${sublabel}</text>
    </svg>`;
}

/** Mini donut for pillar breakdown */
function miniDonut(pct: number, color: string, label: string): string {
  const r = 19;
  const circ = 2 * Math.PI * r;
  const dash = (Math.min(pct, 100) / 100) * circ;
  const c = pctColor(pct);
  return `
    <div style="display:flex;flex-direction:column;align-items:center;gap:3px;flex:1;min-width:0">
      <svg width="52" height="52" viewBox="0 0 52 52" xmlns="http://www.w3.org/2000/svg">
        <circle cx="26" cy="26" r="${r}" fill="none" stroke="#E8F0F8" stroke-width="5.5"/>
        <circle cx="26" cy="26" r="${r}" fill="none" stroke="${c}" stroke-width="5.5"
          stroke-linecap="round"
          stroke-dasharray="${dash.toFixed(2)} ${circ.toFixed(2)}"
          transform="rotate(-90 26 26)"/>
        <text x="26" y="30" text-anchor="middle" font-size="11" font-weight="800"
          fill="${c}" font-family="Arial,sans-serif">${pct}%</text>
      </svg>
      <div style="font-size:8.5px;color:#64748B;text-align:center;font-weight:700;line-height:1.2">${label}</div>
    </div>`;
}

/** Horizontal progress bar */
function bar(pct: number, color: string, h = 7): string {
  return `<div style="height:${h}px;background:#E8F0F8;border-radius:${h/2}px;overflow:hidden">
    <div style="height:${h}px;width:${Math.min(pct,100)}%;background:${color};border-radius:${h/2}px"></div>
  </div>`;
}

/** Gradient bar */
function gradBar(pct: number, c1: string, c2: string, h = 7): string {
  return `<div style="height:${h}px;background:#E8F0F8;border-radius:${h/2}px;overflow:hidden">
    <div style="height:${h}px;width:${Math.min(pct,100)}%;background:linear-gradient(90deg,${c1},${c2});border-radius:${h/2}px"></div>
  </div>`;
}

/** SVG bar chart */
function barChart(values: number[], labels: string[], color: string, w = 680, h = 80): string {
  const max = Math.max(...values, 1);
  const n = values.length;
  const barW = Math.floor((w - (n - 1) * 4) / n);
  const bars = values.map((v, i) => {
    const bh = v > 0 ? Math.max(6, Math.round((v / max) * (h - 20))) : 3;
    const x = i * (barW + 4);
    const y = h - 18 - bh;
    const c = v > 0 ? color : "#E8F0F8";
    const lbl = labels[i] || "";
    const valLbl = v > 0 ? String(v) : "";
    return `
      <rect x="${x}" y="${y}" width="${barW}" height="${bh}" fill="${c}" rx="3"/>
      ${v > 0 ? `<text x="${x + barW/2}" y="${y - 3}" text-anchor="middle" font-size="9" fill="${color}" font-weight="700">${valLbl}</text>` : ""}
      <text x="${x + barW/2}" y="${h - 2}" text-anchor="middle" font-size="8.5" fill="#94A3B8">${lbl.slice(0,3)}</text>`;
  }).join("");
  return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg">${bars}</svg>`;
}

/** Page header used on non-cover pages */
function miniHeader(sectionName: string, P: string, A: string, dateFrom: Date, dateTo: Date, periodLabel: string): string {
  return `
    <div style="background:linear-gradient(135deg,${P} 0%,${A} 100%);padding:12px 20px;display:flex;align-items:center;justify-content:space-between;flex-shrink:0">
      <div style="display:flex;align-items:center;gap:10px">
        ${logoImg(26)}
        <div>
          <div style="color:#fff;font-size:13px;font-weight:900;letter-spacing:0.3px">AORANE HEALTH</div>
          <div style="color:rgba(255,255,255,0.65);font-size:8px;font-weight:600;letter-spacing:1px;text-transform:uppercase">Health Intelligence Report</div>
        </div>
      </div>
      <div style="text-align:right">
        <div style="color:#fff;font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:0.8px">${sectionName}</div>
        <div style="color:rgba(255,255,255,0.65);font-size:8.5px;margin-top:1px">${fmtDate(dateFrom)} — ${fmtDate(dateTo)} · ${periodLabel}</div>
      </div>
    </div>`;
}

function sectionTitle(title: string, badge?: string, badgeColor = "#0077B6"): string {
  return `<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;padding-bottom:8px;border-bottom:1.5px solid #F0F4F8">
    <div style="font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:0.8px;color:#1E293B">${title}</div>
    ${badge ? `<div style="font-size:8.5px;font-weight:800;padding:3px 10px;border-radius:20px;background:${badgeColor}18;color:${badgeColor};text-transform:uppercase;letter-spacing:0.3px">${badge}</div>` : ""}
  </div>`;
}

function pageFooter(reportId: string, generatedAt: Date, page: number, totalPages: number, P: string): string {
  return `<div style="background:#F8FAFC;border-top:1px solid #E2E8F0;padding:8px 20px;display:flex;align-items:center;justify-content:space-between;flex-shrink:0;margin-top:auto">
    <div style="font-size:8.5px;font-weight:800;color:${P}">AORANE HEALTH</div>
    <div style="font-size:8.5px;color:#94A3B8">Report ID: <strong style="color:#64748B">${reportId || "—"}</strong> · Generated: ${fmtDate(generatedAt)}</div>
    <div style="font-size:8.5px;font-weight:700;color:#94A3B8">Page ${page} of ${totalPages}</div>
  </div>`;
}

// ─── Main builder ─────────────────────────────────────────────

export function buildHealthReport(d: ReportData): string {
  if (!d) return "<h1>Error: Missing Report Data</h1>";

  const P = d.primaryColor || "#0077B6";
  const A = d.accentColor || "#00B4D8";
  const isWeekly = d.reportType === "weekly";
  const periodDays = d.periodDays || (isWeekly ? 7 : 30);
  const periodLabel = isWeekly ? "7-Day" : `${periodDays}-Day`;
  const TOTAL_PAGES = 4;

  // ── Aggregate dailyLogs ──────────────────────────────────
  const allLogs = Array.isArray(d.dailyLogs) ? d.dailyLogs : [];
  const validLogs = allLogs.filter(l => (l?.healthScore || 0) > 0);
  const vc = validLogs.length || 1;

  const avgStress   = Math.round(validLogs.reduce((s, l) => s + (l?.stressLevel || 0), 0) / vc);
  const avgWater    = (validLogs.reduce((s, l) => s + (l?.waterGlasses || 0), 0) / vc).toFixed(1);
  const avgCalIn    = Math.round(validLogs.reduce((s, l) => s + (l?.caloriesIn || 0), 0) / vc);
  const avgCalBurn  = Math.round(validLogs.reduce((s, l) => s + (l?.caloriesBurned || 0), 0) / vc);
  const avgEx       = Math.round(validLogs.reduce((s, l) => s + (l?.exerciseMinutes || 0), 0) / vc);
  const avgSleepRaw = validLogs.reduce((s, l) => s + ((l as any)?.sleepHours || 0), 0) / vc;
  const sleepH      = Math.floor(avgSleepRaw);
  const sleepM      = Math.round((avgSleepRaw - sleepH) * 60);
  const sleepDisp   = avgSleepRaw > 0 ? `${sleepH}h ${sleepM}m` : "—";

  // ── Medicine: correct calculation ─────────────────────────
  // medsTotal=0 means no medication scheduled (no data), not 100% compliance
  const medsTaken = allLogs.reduce((s, l) => s + (l?.medicinesTaken || 0), 0);
  const medsTotal = allLogs.reduce((s, l) => s + (l?.medicinesTotal || 0), 0);
  const medPct    = medsTotal > 0 ? Math.round((medsTaken / medsTotal) * 100) : 0;
  const medMissed = Math.max(0, medsTotal - medsTaken);

  const avgScore   = d.scores?.periodAvgScore || 0;
  const activePct  = d.scores?.activePercent || 0;
  const streakDays = d.scores?.streakDays || 0;

  // ── Pillar scores from ReportData.scores ─────────────────
  const foodPct     = d.scores?.foodPct     || 0;
  const waterPct    = d.scores?.waterPct    || 0;
  const exercisePct = d.scores?.exercisePct || 0;
  const sleepPct    = d.scores?.sleepPct    || 0;
  const stressPct   = d.scores?.stressPct   || 0;
  // medicinePct: re-derive from logs, same as medPct above (authoritative)
  const medicinePct = medPct;

  const actualAge  = d.profile?.age ?? null;
  const healthAge  = actualAge
    ? calcHealthAge(actualAge, avgScore, d.risks?.stressRisk || "Low", d.profile?.bmiCategory || null, medPct, activePct)
    : null;

  // ── Risk levels ──────────────────────────────────────────
  const hr = d.risks?.hydrationRisk || "Low";
  const nr = d.risks?.nutritionRisk || "Low";
  const sr = d.risks?.stressRisk || "Low";
  const sleepRisk: "Low" | "Moderate" | "High"    = sleepPct >= 80 ? "Low" : sleepPct >= 50 ? "Moderate" : "High";
  const activityRisk: "Low" | "Moderate" | "High" = activePct >= 70 ? "Low" : activePct >= 40 ? "Moderate" : "High";
  const medRisk: "Low" | "Moderate" | "High"      = medsTotal === 0 ? "Low" : medPct >= 85 ? "Low" : medPct >= 60 ? "Moderate" : "High";

  // ── Seasonal guide ───────────────────────────────────────
  const sgMap: Record<string, { title: string; color: string; bg: string; border: string; tips: string[] }> = {
    summer:  { title: "Summer Health Protocol",  color: "#B45309", bg: "#FFFBEB", border: "#FDE68A",
                tips: ["Maintain 10–12 glasses of water daily to prevent heat stroke.", "Avoid direct sun between 11 AM and 4 PM.", "Include hydrating foods: cucumber, watermelon, coconut water.", "Wear light clothing and use SPF 30+ sunscreen."] },
    monsoon: { title: "Monsoon Health Protocol", color: "#1D4ED8", bg: "#EFF6FF", border: "#BFDBFE",
                tips: ["Consume only boiled or purified water to prevent waterborne illness.", "Avoid street food — risk of gastrointestinal infection is elevated.", "Boost immunity with Vitamin C-rich foods: citrus, guava, amla.", "Keep feet dry; fungal infections are common during monsoon."] },
    winter:  { title: "Winter Health Protocol",  color: "#1E3A5F", bg: "#F0F9FF", border: "#BAE6FD",
                tips: ["Drink warm herbal teas — ginger, tulsi, or cinnamon-based.", "Get 15–20 minutes of morning sunlight for natural Vitamin D.", "Include dry fruits and nuts for sustained energy and immunity.", "Exercise indoors; maintain activity despite cold temperatures."] },
    spring:  { title: "Spring Health Protocol",  color: "#065F46", bg: "#ECFDF5", border: "#A7F3D0",
                tips: ["Take allergy precautions — pollen levels peak this season.", "Incorporate fresh seasonal fruits and green leafy vegetables.", "Enjoy outdoor walks — morning air quality is optimal.", "Gradually increase exercise intensity after winter."] },
  };
  const season = d.weather?.season?.toLowerCase() || "summer";
  const guide  = sgMap[season] || sgMap.summer;

  // ── AI predictions ───────────────────────────────────────
  const trend30Score = Math.min(100, Math.max(0, Math.round(avgScore + (activePct >= 60 ? 3 : -2) + (hr === "Low" ? 2 : -1))));
  const trend90Score = Math.min(100, Math.max(0, Math.round(avgScore + (activePct >= 60 ? 8 : -5) + (nr === "Low" ? 4 : -2))));
  const lifestyleRisk: "Low" | "Moderate" | "High" = avgScore >= 70 ? "Low" : avgScore >= 50 ? "Moderate" : "High";
  const wellnessRisk: "Low" | "Moderate" | "High"  = avgScore >= 75 ? "Low" : avgScore >= 55 ? "Moderate" : "High";
  const weightRisk: "Low" | "Moderate" | "High"    = d.profile?.bmiCategory === "Normal" ? "Low" : d.profile?.bmiCategory === "Overweight" ? "Moderate" : "High";

  // ── Medical flags ─────────────────────────────────────────
  type FlagLevel = "critical" | "warning" | "info";
  const flags: { level: FlagLevel; msg: string; detail: string }[] = [];
  if (hr === "High")       flags.push({ level: "critical", msg: "Severe Dehydration Risk", detail: "Fluid intake is critically low. Increase water consumption immediately." });
  else if (hr === "Moderate") flags.push({ level: "warning", msg: "Moderate Dehydration", detail: "Target 6–8 glasses of water daily." });
  if (nr === "High")       flags.push({ level: "warning", msg: "Poor Nutritional Intake", detail: "Multiple macro and micronutrients are below required targets." });
  if (sr === "High")       flags.push({ level: "warning", msg: "Elevated Stress Markers", detail: "Chronic stress increases cardiovascular risk. Seek professional guidance." });
  if (medsTotal > 0 && medPct < 60) flags.push({ level: "warning", msg: "Low Medication Compliance", detail: `${medPct}% adherence recorded. Missing doses reduces treatment efficacy significantly.` });
  if (sleepRisk === "High") flags.push({ level: "warning", msg: "Insufficient Sleep", detail: "Sleep deprivation impairs recovery and immunity. Target 7–9 hours nightly." });
  if (flags.length === 0)  flags.push({ level: "info", msg: "No Critical Health Anomalies", detail: "All monitored health markers are within acceptable ranges. Continue your current wellness routine." });

  const fColor  = { critical: "#991B1B", warning: "#92400E", info: "#065F46" };
  const fBg     = { critical: "#FEF2F2", warning: "#FFFBEB", info: "#ECFDF5" };
  const fBorder = { critical: "#EF4444", warning: "#F59E0B", info: "#10B981" };

  // ── AI key findings ──────────────────────────────────────
  const aiFindings = [
    avgScore >= 70 ? `Health score of ${avgScore}/100 indicates ${getStatus(avgScore).toLowerCase()} overall wellness.` : `Health score of ${avgScore}/100 requires focused improvement across key lifestyle areas.`,
    activePct >= 70 ? `Active participation at ${activePct}% reflects consistent engagement with daily health goals.` : `Activity rate of ${activePct}% is below the recommended 70% threshold.`,
    hr === "Low" ? "Hydration is well-maintained throughout the reporting period." : `Hydration risk flagged as ${hr} — water intake requires immediate attention.`,
    avgEx >= 30 ? `Average exercise duration of ${avgEx} min/day meets WHO recommendations.` : `Exercise duration averages only ${avgEx || 0} min — increase toward the 30-min daily target.`,
  ];

  const logScores = allLogs.map(l => l?.healthScore || 0);
  const logDays   = allLogs.map(l => (l?.dayName || l?.date?.slice(5) || "").slice(0, 3));

  // ── Nutrition data ───────────────────────────────────────
  const nut = d.nutrition || ({} as any);
  const t   = nut.targets  || ({} as any);
  const allNutZero = !nut.protein_g && !nut.carbs_g && !nut.fat_g;

  const pillars = [
    { label: "Nutrition",   pct: foodPct,     color: "#10B981" },
    { label: "Hydration",   pct: waterPct,    color: "#0EA5E9" },
    { label: "Exercise",    pct: exercisePct, color: "#8B5CF6" },
    { label: "Sleep",       pct: sleepPct,    color: "#6366F1" },
    { label: "Low Stress",  pct: stressPct,   color: "#F59E0B" },
    { label: "Medication",  pct: medicinePct, color: "#3B82F6" },
  ];

  // ════════════════════════════════════════════════════════
  //  PAGE 1 — COVER + MEMBER PROFILE + HEALTH SCORE + PILLARS
  // ════════════════════════════════════════════════════════
  const page1 = `
  <div class="page" id="page-1">
    <div class="watermark">AORANE HEALTH INTELLIGENCE REPORT</div>

    <!-- Cover Header -->
    <div class="cover-hdr">
      <div style="display:flex;align-items:center;gap:14px;margin-bottom:14px;position:relative;z-index:1">
        ${logoImg(48)}
        <div>
          <div style="color:#fff;font-size:26px;font-weight:900;letter-spacing:0.5px;line-height:1">AORANE</div>
          <div style="color:rgba(255,255,255,0.65);font-size:9px;font-weight:600;letter-spacing:2px;text-transform:uppercase;margin-top:2px">Health Intelligence Report</div>
        </div>
        <div style="margin-left:auto;text-align:right;position:relative;z-index:1">
          <div style="background:rgba(255,255,255,0.18);border:1px solid rgba(255,255,255,0.3);border-radius:10px;padding:7px 12px;display:inline-block">
            <div style="color:rgba(255,255,255,0.55);font-size:7.5px;font-weight:700;letter-spacing:1px;text-transform:uppercase">Report ID</div>
            <div style="color:#fff;font-size:10.5px;font-weight:800;font-family:monospace;margin-top:1px">${d.reportId || "—"}</div>
          </div>
        </div>
      </div>
      <div style="position:relative;z-index:1;display:flex;align-items:center;justify-content:space-between">
        <div>
          <div style="display:inline-block;background:rgba(255,255,255,0.2);border:1px solid rgba(255,255,255,0.35);border-radius:20px;padding:3px 14px;color:#fff;font-size:10px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase">
            ${isWeekly ? "7-Day Weekly" : `${periodDays}-Day Monthly`} Report
          </div>
          <div style="color:rgba(255,255,255,0.65);font-size:10px;font-weight:500;margin-top:5px">${fmtDay(d.dateFrom)} — ${fmtDay(d.dateTo)}</div>
        </div>
        <div style="text-align:right;color:rgba(255,255,255,0.7);font-size:9.5px">
          <div>Generated: ${fmtDate(d.generatedAt)}</div>
          <div style="margin-top:2px">Powered by Aorane AI</div>
        </div>
      </div>
    </div>

    <!-- Two-column: Member Profile + Health Score -->
    <div style="display:flex;gap:0;flex:1">

      <!-- Left: Profile -->
      <div style="flex:1;padding:16px 14px 14px 20px;border-right:1px solid #F0F4F8">
        ${sectionTitle("Member Profile", `Plan: ${d.profile?.plan || "—"}`, "#0077B6")}

        <div style="display:flex;align-items:center;gap:12px;margin-bottom:14px">
          <div style="width:50px;height:50px;border-radius:50%;background:linear-gradient(135deg,${P},${A});display:flex;align-items:center;justify-content:center;color:#fff;font-size:22px;font-weight:900;flex-shrink:0">
            ${(d.profile?.name || "U").charAt(0).toUpperCase()}
          </div>
          <div>
            <div style="font-size:17px;font-weight:900;color:#0F172A;line-height:1.1">${d.profile?.name || "—"}</div>
            <div style="font-size:9px;font-weight:700;color:#64748B;margin-top:3px">
              <span style="background:#E2E8F0;padding:2px 7px;border-radius:5px;font-family:monospace">${d.profile?.aoraneId || "—"}</span>
            </div>
            <div style="font-size:10px;color:#64748B;margin-top:3px">${[d.profile?.gender, d.profile?.city, d.profile?.state].filter(Boolean).join(" · ")}</div>
          </div>
        </div>

        <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:7px">
          ${[
            { lbl: "Height",     val: d.profile?.height_cm ? `${d.profile.height_cm} cm` : "—" },
            { lbl: "Weight",     val: d.profile?.weight_kg ? `${d.profile.weight_kg} kg` : "—" },
            { lbl: "BMI",        val: d.profile?.bmi || "—", sub: d.profile?.bmiCategory || "" },
            { lbl: "Blood Group",val: d.profile?.bloodGroup || "—" },
            { lbl: "Member Since",val: d.profile?.memberSince ? d.profile.memberSince.split("T")[0] : "—" },
            { lbl: "Health Age", val: healthAge ? `${healthAge} yrs` : "—", sub: actualAge ? `Actual: ${actualAge} yrs` : "" },
          ].map(s => `
            <div style="background:#F8FAFC;border:1px solid #E8F0F8;border-radius:10px;padding:9px 11px">
              <div style="font-size:7.5px;color:#94A3B8;text-transform:uppercase;font-weight:700;letter-spacing:0.4px;margin-bottom:3px">${s.lbl}</div>
              <div style="font-size:13px;font-weight:800;color:#0F172A">${s.val}</div>
              ${(s as any).sub ? `<div style="font-size:8px;color:#64748B;margin-top:1px">${(s as any).sub}</div>` : ""}
            </div>`).join("")}
        </div>

        <!-- Executive summary bullets -->
        <div style="margin-top:12px;background:linear-gradient(135deg,${P}06,${A}08);border:1px solid ${P}15;border-radius:10px;padding:11px 13px">
          <div style="font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:0.6px;color:#475569;margin-bottom:8px">Executive Health Summary</div>
          ${aiFindings.map((f, i) => `
            <div style="display:flex;align-items:flex-start;gap:7px;padding:4px 0;border-bottom:1px solid ${P}10">
              <div style="width:7px;height:7px;border-radius:50%;background:${i < 2 ? "#059669" : pctColor(activePct)};flex-shrink:0;margin-top:3px"></div>
              <div style="font-size:10px;color:#334155;line-height:1.5;font-weight:500">${f}</div>
            </div>`).join("")}
        </div>
      </div>

      <!-- Right: Health Score + Pillars -->
      <div style="flex:1;padding:16px 20px 14px 14px">
        ${sectionTitle("Health Score Overview", `Grade ${getGrade(avgScore)}`, scoreColor(avgScore))}

        <!-- Score ring + side stats -->
        <div style="display:flex;gap:12px;align-items:stretch;margin-bottom:14px">
          <div style="display:flex;flex-direction:column;align-items:center;justify-content:center;background:linear-gradient(135deg,${P}08,${A}0A);border:1.5px solid ${P}22;border-radius:14px;padding:16px 12px;flex-shrink:0">
            ${scoreRing(avgScore, 115, periodLabel + " AVG", `Grade ${getGrade(avgScore)}`, scoreColor(avgScore))}
            <div style="font-size:8px;font-weight:700;text-transform:uppercase;letter-spacing:0.4px;color:#475569;margin-top:6px">${periodLabel} Average</div>
            <div style="display:inline-block;border-radius:8px;padding:4px 16px;font-size:20px;font-weight:900;color:#fff;background:${scoreColor(avgScore)};margin-top:4px">${getGrade(avgScore)}</div>
            <div style="font-size:10px;font-weight:700;color:${scoreColor(avgScore)};margin-top:4px">${getStatus(avgScore)}</div>
          </div>

          <div style="display:flex;flex-direction:column;gap:8px;flex:1">
            <div style="background:#F8FAFC;border:1px solid #E8F0F8;border-radius:11px;padding:11px 13px;flex:1">
              <div style="font-size:8.5px;font-weight:700;text-transform:uppercase;color:#64748B;margin-bottom:4px">Active Days</div>
              <div style="font-size:22px;font-weight:900;color:${pctColor(activePct)}">${activePct}%</div>
              <div style="font-size:9px;color:#64748B;margin-top:1px">of ${periodDays} days tracked</div>
              ${gradBar(activePct, pctColor(activePct), pctColor(activePct) + "88", 5)}
            </div>
            <div style="background:#F8FAFC;border:1px solid #E8F0F8;border-radius:11px;padding:11px 13px;flex:1">
              <div style="font-size:8.5px;font-weight:700;text-transform:uppercase;color:#64748B;margin-bottom:4px">Streak</div>
              <div style="font-size:22px;font-weight:900;color:${P}">${streakDays} <span style="font-size:13px;font-weight:700;color:#64748B">days</span></div>
              <div style="font-size:9px;color:#64748B;margin-top:1px">consecutive active days</div>
            </div>
            <div style="background:#F8FAFC;border:1px solid #E8F0F8;border-radius:11px;padding:11px 13px;flex:1">
              <div style="font-size:8.5px;font-weight:700;text-transform:uppercase;color:#64748B;margin-bottom:4px">Wellness Status</div>
              <div style="font-size:14px;font-weight:800;color:${scoreColor(avgScore)};margin-top:2px">${getStatus(avgScore)}</div>
              <div style="font-size:9px;color:#64748B;margin-top:1px">${avgScore >= 70 ? "On track with health goals" : "Focused improvement needed"}</div>
            </div>
          </div>
        </div>

        <!-- 6 Pillars row -->
        ${sectionTitle("Health Pillars Breakdown")}
        <div style="background:#F8FAFC;border:1px solid #E8F0F8;border-radius:12px;padding:12px">
          <div style="display:flex;justify-content:space-around;gap:4px">
            ${pillars.map(p => miniDonut(p.pct, p.color, p.label)).join("")}
          </div>
        </div>

        <!-- Pillar detail bars -->
        <div style="display:flex;flex-direction:column;gap:7px;margin-top:10px">
          ${pillars.map(p => {
            const desc =
              p.label === "Nutrition"  ? (p.pct >= 80 ? "Excellent dietary habits" : p.pct >= 50 ? "Moderate nutrition" : "Nutritional gaps") :
              p.label === "Hydration"  ? (p.pct >= 80 ? "Well hydrated" : p.pct >= 50 ? "Slightly low intake" : "Dehydration risk") :
              p.label === "Exercise"   ? (p.pct >= 80 ? "Highly active" : p.pct >= 50 ? "Moderate activity" : "Needs more movement") :
              p.label === "Sleep"      ? (p.pct >= 80 ? "Excellent sleep quality" : p.pct >= 50 ? "Average sleep" : "Poor sleep pattern") :
              p.label === "Low Stress" ? (p.pct >= 80 ? "Low stress levels" : p.pct >= 50 ? "Moderate stress" : "High stress detected") :
              /* Medication */            (medsTotal === 0 ? "No medication scheduled" : p.pct >= 85 ? "Excellent adherence" : p.pct >= 60 ? "Partial compliance" : "Low compliance");
            const c = pctColor(p.pct);
            return `
              <div style="display:flex;align-items:center;gap:9px;background:#F8FAFC;border:1px solid #E8F0F8;border-radius:10px;padding:8px 11px">
                <div style="flex:1">
                  <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
                    <span style="font-size:10px;font-weight:700;color:#1E293B">${p.label}</span>
                    <div style="display:flex;align-items:center;gap:7px">
                      <span style="font-size:9px;color:#64748B">${desc}</span>
                      <span style="font-size:11px;font-weight:900;color:${c}">${p.pct}%</span>
                    </div>
                  </div>
                  ${gradBar(p.pct, c, c + "88", 6)}
                </div>
              </div>`;
          }).join("")}
        </div>
      </div>
    </div>

    ${pageFooter(d.reportId || "—", d.generatedAt, 1, TOTAL_PAGES, P)}
  </div>`;

  // ════════════════════════════════════════════════════════
  //  PAGE 2 — VITALS + HEALTH LOG + NUTRITION
  // ════════════════════════════════════════════════════════
  const page2 = `
  <div class="page" id="page-2">
    <div class="watermark">AORANE HEALTH INTELLIGENCE REPORT</div>
    ${miniHeader("Vitals & Health Log", P, A, d.dateFrom, d.dateTo, periodLabel)}

    <div style="padding:14px 20px;flex:1;display:flex;flex-direction:column;gap:12px">

      <!-- Vitals KPI row -->
      ${sectionTitle("Vitals Overview", `${periodLabel} Averages`, "#991B1B")}
      <div style="display:flex;gap:8px;margin-bottom:2px">
        ${[
          { lbl: "Water / Day",  val: `${avgWater}`,       sub: "glasses · 7-Day",  trend: Number(avgWater) >= 8 ? "↑ Optimal" : "↓ Low", tColor: Number(avgWater) >= 8 ? "#059669" : "#F97316" },
          { lbl: "Calories In",  val: avgCalIn > 0 ? `${avgCalIn}` : "—", sub: "kcal/day · Avg",   trend: "", tColor: "#64748B" },
          { lbl: "Cal. Burned",  val: avgCalBurn > 0 ? `${avgCalBurn}` : "—", sub: "kcal/day · Avg", trend: "", tColor: "#64748B" },
          { lbl: "Exercise",     val: avgEx > 0 ? `${avgEx}` : "—",       sub: "min/day · Avg",   trend: avgEx >= 30 ? "↑ Good" : "↓ Low", tColor: avgEx >= 30 ? "#059669" : "#F97316" },
          { lbl: "Avg Sleep",    val: sleepDisp,            sub: "per night · Avg", trend: avgSleepRaw >= 7 ? "↑ Good" : "↓ Low", tColor: avgSleepRaw >= 7 ? "#059669" : "#F97316" },
          { lbl: "Stress Level", val: avgStress > 0 ? `${avgStress}` : "—", sub: "avg score · Avg", trend: avgStress < 40 ? "↓ Low" : avgStress < 70 ? "→ Moderate" : "↑ High", tColor: avgStress < 40 ? "#059669" : avgStress < 70 ? "#F59E0B" : "#EF4444" },
        ].map(v => `
          <div style="flex:1;background:#F8FAFC;border:1px solid #E8F0F8;border-radius:12px;padding:10px 8px;text-align:center">
            <div style="font-size:7.5px;color:#94A3B8;text-transform:uppercase;font-weight:700;letter-spacing:0.3px;margin-bottom:3px">${v.lbl}</div>
            <div style="font-size:16px;font-weight:900;color:#0F172A">${v.val}</div>
            <div style="font-size:8px;color:#64748B;margin-top:1px">${v.sub}</div>
            ${v.trend ? `<div style="font-size:9px;font-weight:800;color:${v.tColor};margin-top:3px">${v.trend}</div>` : ""}
          </div>`).join("")}
      </div>

      <!-- Health Score Bar Chart -->
      <div style="background:#F8FAFC;border:1px solid #E8F0F8;border-radius:12px;padding:12px">
        <div style="font-size:9.5px;font-weight:800;text-transform:uppercase;letter-spacing:0.5px;color:#64748B;margin-bottom:8px">Daily Health Score — ${periodLabel} Trend</div>
        ${barChart(logScores, logDays, scoreColor(avgScore), 640, 80)}
      </div>

      <!-- Day Health Log Table -->
      <div>
        ${sectionTitle(isWeekly ? "7-Day Health Log" : "Monthly Health Log Summary")}
        <div style="overflow:hidden;border-radius:10px;border:1px solid #E8F0F8">
          <table style="width:100%;border-collapse:collapse;font-size:9.5px">
            <thead>
              <tr style="background:#F8FAFC">
                <th style="padding:7px 8px;text-align:left;font-size:8px;color:#64748B;text-transform:uppercase;font-weight:700;border-bottom:1.5px solid #E8F0F8">Date</th>
                <th style="padding:7px 6px;text-align:center;font-size:8px;color:#64748B;text-transform:uppercase;font-weight:700;border-bottom:1.5px solid #E8F0F8">Score</th>
                <th style="padding:7px 6px;text-align:center;font-size:8px;color:#64748B;text-transform:uppercase;font-weight:700;border-bottom:1.5px solid #E8F0F8">Water</th>
                <th style="padding:7px 6px;text-align:center;font-size:8px;color:#64748B;text-transform:uppercase;font-weight:700;border-bottom:1.5px solid #E8F0F8">Cal. In</th>
                <th style="padding:7px 6px;text-align:center;font-size:8px;color:#64748B;text-transform:uppercase;font-weight:700;border-bottom:1.5px solid #E8F0F8">Cal. Burned</th>
                <th style="padding:7px 6px;text-align:center;font-size:8px;color:#64748B;text-transform:uppercase;font-weight:700;border-bottom:1.5px solid #E8F0F8">Exercise</th>
                <th style="padding:7px 6px;text-align:center;font-size:8px;color:#64748B;text-transform:uppercase;font-weight:700;border-bottom:1.5px solid #E8F0F8">Sleep</th>
                <th style="padding:7px 6px;text-align:center;font-size:8px;color:#64748B;text-transform:uppercase;font-weight:700;border-bottom:1.5px solid #E8F0F8">Stress</th>
              </tr>
            </thead>
            <tbody>
              ${allLogs.slice(0, 31).map((l, i) => {
                const sc = l?.healthScore || 0;
                const sColor = sc > 0 ? scoreColor(sc) : "#94A3B8";
                const row = [
                  `<td style="padding:6px 8px;font-size:9px;font-weight:700;color:#334155;border-bottom:1px solid #F1F5F9">
                    <div>${l?.dayName || ""}</div><div style="font-size:8px;color:#94A3B8">${l?.date || ""}</div>
                  </td>`,
                  `<td style="padding:6px;text-align:center;border-bottom:1px solid #F1F5F9">
                    ${sc > 0 ? `<span style="display:inline-block;background:${sColor}18;color:${sColor};border-radius:12px;padding:2px 7px;font-size:9.5px;font-weight:800">${sc}</span>` : `<span style="color:#CBD5E1">—</span>`}
                  </td>`,
                  `<td style="padding:6px;text-align:center;border-bottom:1px solid #F1F5F9;font-size:9.5px;font-weight:600;color:#0EA5E9">${l?.waterGlasses ? l.waterGlasses + "gl" : "—"}</td>`,
                  `<td style="padding:6px;text-align:center;border-bottom:1px solid #F1F5F9;font-size:9.5px;font-weight:600;color:#F97316">${l?.caloriesIn || "—"}</td>`,
                  `<td style="padding:6px;text-align:center;border-bottom:1px solid #F1F5F9;font-size:9.5px;font-weight:600;color:#10B981">${l?.caloriesBurned || "—"}</td>`,
                  `<td style="padding:6px;text-align:center;border-bottom:1px solid #F1F5F9;font-size:9.5px;font-weight:600;color:#8B5CF6">${l?.exerciseMinutes ? l.exerciseMinutes + "m" : "—"}</td>`,
                  `<td style="padding:6px;text-align:center;border-bottom:1px solid #F1F5F9;font-size:9.5px;font-weight:600;color:#6366F1">${(l as any)?.sleepHours ? (l as any).sleepHours + "h" : "—"}</td>`,
                  `<td style="padding:6px;text-align:center;border-bottom:1px solid #F1F5F9;font-size:9.5px;font-weight:600;color:#F59E0B">${l?.stressLevel || "—"}</td>`,
                ].join("");
                return `<tr style="background:${i % 2 === 0 ? "#fff" : "#FAFBFC"}">${row}</tr>`;
              }).join("")}
              <tr style="background:${P}08;font-weight:800">
                <td style="padding:7px 8px;font-size:9.5px;font-weight:800;color:${P}">7-Day Avg</td>
                <td style="padding:7px 6px;text-align:center;font-size:10px;font-weight:900;color:${scoreColor(avgScore)}">${avgScore}</td>
                <td style="padding:7px 6px;text-align:center;font-size:10px;font-weight:800;color:#0EA5E9">${avgWater}</td>
                <td style="padding:7px 6px;text-align:center;font-size:10px;font-weight:800;color:#F97316">${avgCalIn || "—"}</td>
                <td style="padding:7px 6px;text-align:center;font-size:10px;font-weight:800;color:#10B981">${avgCalBurn || "—"}</td>
                <td style="padding:7px 6px;text-align:center;font-size:10px;font-weight:800;color:#8B5CF6">${avgEx > 0 ? avgEx + "m" : "—"}</td>
                <td style="padding:7px 6px;text-align:center;font-size:10px;font-weight:800;color:#6366F1">${sleepDisp}</td>
                <td style="padding:7px 6px;text-align:center;font-size:10px;font-weight:800;color:#F59E0B">${avgStress || "—"}</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>

      <!-- Nutrition Summary (compact) -->
      <div>
        ${sectionTitle("Nutrition Intelligence", `${periodLabel} Totals vs Targets`, "#92400E")}
        ${allNutZero ? `
          <div style="background:#FFF7ED;border:1px solid #FED7AA;border-radius:10px;padding:16px;text-align:center">
            <div style="color:#9A3412;font-size:11.5px;font-weight:700;margin-bottom:4px">No food logs found for this period</div>
            <div style="color:#B45309;font-size:10px">Start tracking meals in the Aorane app to unlock nutrition insights.</div>
          </div>` : `
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">
            ${[
              { l: "Protein",      v: nut.protein_g    || 0, max: t.protein_g    || 0, u: "g",   c: "#EF4444" },
              { l: "Carbohydrates",v: nut.carbs_g      || 0, max: t.carbs_g      || 0, u: "g",   c: "#F59E0B" },
              { l: "Fat",          v: nut.fat_g        || 0, max: t.fat_g        || 0, u: "g",   c: "#10B981" },
              { l: "Fiber",        v: nut.fiber_g      || 0, max: 25 * periodDays, u: "g",   c: "#8B5CF6" },
            ].map(n => {
              const pct = n.max > 0 ? Math.min(100, Math.round((n.v / n.max) * 100)) : 0;
              const sc  = pct >= 80 ? "#059669" : pct >= 50 ? "#F59E0B" : "#EF4444";
              return `
                <div style="background:#F8FAFC;border:1px solid #E8F0F8;border-radius:10px;padding:10px 12px">
                  <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px">
                    <span style="font-size:10.5px;font-weight:700;color:#1E293B">${n.l}</span>
                    <span style="font-size:11px;font-weight:900;color:${sc}">${pct}%</span>
                  </div>
                  <div style="font-size:9px;color:#94A3B8;margin-bottom:5px">${n.v > 0 ? `${n.v}${n.u}` : "—"} / ${n.max}${n.u}</div>
                  ${gradBar(pct, n.c + "99", n.c, 6)}
                </div>`;
            }).join("")}
          </div>`}
      </div>
    </div>

    ${pageFooter(d.reportId || "—", d.generatedAt, 2, TOTAL_PAGES, P)}
  </div>`;

  // ════════════════════════════════════════════════════════
  //  PAGE 3 — ACTIVITY + MEDICATION + RISK DASHBOARD + AI PREDICTION
  // ════════════════════════════════════════════════════════
  const medStatus      = medsTotal === 0 ? "Not Tracked" : medPct >= 85 ? "Excellent" : medPct >= 70 ? "Good" : medPct >= 50 ? "Needs Attention" : "Critical";
  const medStatusColor = medsTotal === 0 ? "#64748B" : medPct >= 85 ? "#059669" : medPct >= 70 ? "#0EA5E9" : medPct >= 50 ? "#F59E0B" : "#EF4444";

  const page3 = `
  <div class="page" id="page-3">
    <div class="watermark">AORANE HEALTH INTELLIGENCE REPORT</div>
    ${miniHeader("Activity · Medication · Risk Analysis", P, A, d.dateFrom, d.dateTo, periodLabel)}

    <div style="display:flex;gap:0;flex:1">

      <!-- Left column: Activity + Medication -->
      <div style="flex:1;padding:14px 12px 14px 20px;border-right:1px solid #F0F4F8;display:flex;flex-direction:column;gap:12px">

        <!-- Activity KPIs -->
        ${sectionTitle("Activity & Fitness Analytics", `${periodLabel} Performance`, "#059669")}
        <div style="display:flex;gap:7px;flex-wrap:wrap">
          ${[
            { lbl: "Active Days",   val: `${Math.round(activePct/100*periodDays)}/${periodDays}`, sub: `${activePct}% active`, c: pctColor(activePct) },
            { lbl: "Avg Exercise",  val: avgEx > 0 ? `${avgEx}m` : "—",       sub: "per session",   c: "#8B5CF6" },
            { lbl: "Cal. Burned",   val: avgCalBurn > 0 ? `${avgCalBurn}` : "—", sub: "kcal/day",   c: "#10B981" },
            { lbl: "Exercise %",    val: `${exercisePct}%`,                      sub: exercisePct >= 80 ? "Excellent" : exercisePct >= 50 ? "Fair" : "Low", c: pctColor(exercisePct) },
          ].map(s => `
            <div style="flex:1;min-width:60px;background:#F8FAFC;border:1px solid #E8F0F8;border-radius:10px;padding:9px 8px;text-align:center">
              <div style="font-size:7.5px;color:#94A3B8;text-transform:uppercase;font-weight:700;margin-bottom:2px">${s.lbl}</div>
              <div style="font-size:14px;font-weight:900;color:${s.c}">${s.val}</div>
              <div style="font-size:8px;color:#64748B;margin-top:1px">${s.sub}</div>
            </div>`).join("")}
        </div>

        <!-- Exercise consistency dots -->
        <div style="background:#F8FAFC;border:1px solid #E8F0F8;border-radius:10px;padding:11px 13px">
          <div style="font-size:8.5px;font-weight:700;text-transform:uppercase;color:#64748B;margin-bottom:8px">Activity Consistency</div>
          <div style="display:flex;gap:4px;flex-wrap:wrap">
            ${allLogs.map(l => {
              const ex = l?.exerciseMinutes || 0;
              const bg = ex >= 30 ? "#059669" : ex > 0 ? "#F59E0B" : "#E8F0F8";
              return `<div style="width:18px;height:18px;border-radius:4px;background:${bg}" title="${l?.dayName||""}: ${ex}m"></div>`;
            }).join("")}
          </div>
          <div style="display:flex;gap:10px;margin-top:7px">
            <span style="font-size:8px;color:#64748B;display:flex;align-items:center;gap:3px"><span style="width:10px;height:10px;background:#059669;border-radius:2px;display:inline-block"></span>≥30 min</span>
            <span style="font-size:8px;color:#64748B;display:flex;align-items:center;gap:3px"><span style="width:10px;height:10px;background:#F59E0B;border-radius:2px;display:inline-block"></span>Active</span>
            <span style="font-size:8px;color:#64748B;display:flex;align-items:center;gap:3px"><span style="width:10px;height:10px;background:#E8F0F8;border-radius:2px;display:inline-block"></span>Inactive</span>
          </div>
        </div>

        <!-- Caloric balance -->
        ${avgCalIn > 0 && avgCalBurn > 0 ? `
          <div style="background:#F8FAFC;border:1px solid #E8F0F8;border-radius:10px;padding:11px 13px">
            <div style="font-size:8.5px;font-weight:700;text-transform:uppercase;color:#64748B;margin-bottom:8px">Caloric Balance</div>
            <div style="margin-bottom:6px">
              <div style="display:flex;justify-content:space-between;font-size:9.5px;margin-bottom:3px">
                <span style="color:#F97316;font-weight:600">Consumed</span><span style="font-weight:800;color:#F97316">${avgCalIn} kcal</span>
              </div>
              ${gradBar(100, "#F97316", "#FCA5A5", 6)}
            </div>
            <div>
              <div style="display:flex;justify-content:space-between;font-size:9.5px;margin-bottom:3px">
                <span style="color:#10B981;font-weight:600">Burned</span><span style="font-weight:800;color:#10B981">${avgCalBurn} kcal</span>
              </div>
              ${gradBar(Math.round((avgCalBurn / avgCalIn) * 100), "#10B981", "#6EE7B7", 6)}
            </div>
            <div style="margin-top:7px;font-size:10px;font-weight:700;color:${avgCalIn-avgCalBurn > 200 ? "#F97316" : "#059669"}">
              Net: ${avgCalIn-avgCalBurn > 0 ? "+" : ""}${avgCalIn-avgCalBurn} kcal/day (${avgCalIn-avgCalBurn > 200 ? "Surplus" : avgCalBurn > avgCalIn ? "Deficit" : "Balanced"})
            </div>
          </div>` : ""}

        <!-- Medication -->
        ${sectionTitle("Medication & Habit Adherence", `${medPct}% Compliance`, "#5B21B6")}
        <div style="display:flex;gap:7px;margin-bottom:10px">
          ${[
            { lbl: "Scheduled", val: medsTotal > 0 ? String(medsTotal) : "—", c: "#64748B" },
            { lbl: "Completed", val: medsTaken > 0 ? String(medsTaken) : "—", c: "#059669" },
            { lbl: "Missed",    val: medMissed > 0 ? String(medMissed) : "—", c: "#EF4444" },
            { lbl: "Compliance",val: medsTotal === 0 ? "N/A" : `${medPct}%`,  c: medStatusColor },
            { lbl: "Status",    val: medStatus,                                c: medStatusColor },
          ].map(s => `
            <div style="flex:1;background:#F8FAFC;border:1px solid #E8F0F8;border-radius:10px;padding:9px 7px;text-align:center">
              <div style="font-size:7px;color:#94A3B8;text-transform:uppercase;font-weight:700;margin-bottom:2px">${s.lbl}</div>
              <div style="font-size:12px;font-weight:800;color:${s.c}">${s.val}</div>
            </div>`).join("")}
        </div>

        <!-- Adherence score bar -->
        <div style="background:#F8FAFC;border:1px solid #E8F0F8;border-radius:10px;padding:11px 13px">
          <div style="display:flex;justify-content:space-between;margin-bottom:5px">
            <div style="font-size:8.5px;font-weight:700;text-transform:uppercase;color:#64748B">Adherence Score</div>
            <div style="font-size:8.5px;color:#64748B">${medPct >= 85 ? "Perfect" : medPct >= 60 ? "Moderate" : medsTotal === 0 ? "Not tracked" : "Critical"}</div>
          </div>
          ${bar(medPct, medStatusColor, 8)}
          <div style="display:flex;justify-content:space-between;margin-top:4px">
            <span style="font-size:8px;color:#94A3B8">0% — Critical</span>
            <span style="font-size:8px;color:#94A3B8">100% — Perfect</span>
          </div>
        </div>

        <!-- Med habit consistency -->
        <div style="background:#F8FAFC;border:1px solid #E8F0F8;border-radius:10px;padding:11px 13px">
          <div style="font-size:8.5px;font-weight:700;text-transform:uppercase;color:#64748B;margin-bottom:8px">Daily Habit Consistency Map</div>
          <div style="display:flex;gap:6px;flex-wrap:wrap">
            ${allLogs.map(l => {
              const taken  = l?.medicinesTaken  || 0;
              const sched  = l?.medicinesTotal  || 0;
              const pct    = sched > 0 ? taken / sched : -1;
              const bg     = pct < 0 ? "#E8F0F8" : pct >= 0.9 ? "#059669" : pct >= 0.5 ? "#F59E0B" : "#EF4444";
              return `<div style="flex:1;min-width:14px;text-align:center">
                <div style="width:100%;height:18px;border-radius:3px;background:${bg}"></div>
                <div style="font-size:7px;color:#94A3B8;margin-top:2px">${(l?.dayName || "").slice(0,1)}</div>
              </div>`;
            }).join("")}
          </div>
          <div style="display:flex;gap:10px;margin-top:5px">
            <span style="font-size:8px;color:#64748B;display:flex;align-items:center;gap:3px"><span style="width:10px;height:10px;background:#059669;border-radius:2px;display:inline-block"></span>On Track</span>
            <span style="font-size:8px;color:#64748B;display:flex;align-items:center;gap:3px"><span style="width:10px;height:10px;background:#F59E0B;border-radius:2px;display:inline-block"></span>Moderate</span>
            <span style="font-size:8px;color:#64748B;display:flex;align-items:center;gap:3px"><span style="width:10px;height:10px;background:#EF4444;border-radius:2px;display:inline-block"></span>Off Track</span>
          </div>
        </div>

        <div style="background:linear-gradient(135deg,#0F172A,#1A2744);border-radius:12px;padding:14px">
          <div style="font-size:11px;font-weight:800;color:#38BDF8;margin-bottom:7px">AI Adherence Intelligence</div>
          <div style="font-size:10.5px;color:#CBD5E1;line-height:1.7">
            ${medsTotal === 0
              ? "No medication schedules found. If you have prescribed medications, set them up in the Aorane app to enable compliance tracking and reminders."
              : medPct >= 85
              ? `Excellent: ${medPct}% medication adherence recorded. Outstanding compliance — continue your current routine.`
              : `Critical: Only <strong>${medPct}%</strong> medication adherence recorded. Consult your physician immediately and use daily alarm reminders for every dose.`}
          </div>
        </div>
      </div>

      <!-- Right column: Risk Dashboard + AI Prediction -->
      <div style="flex:1;padding:14px 20px 14px 12px;display:flex;flex-direction:column;gap:12px">

        ${sectionTitle("Health Risk Dashboard", "Centralized Risk Assessment", "#991B1B")}

        <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px">
          ${[
            { name: "Hydration",   risk: hr,           score: d.risks?.hydrationScore || 0, tip: hr === "High" ? "Critical dehydration. Increase fluid intake immediately." : hr === "Moderate" ? "Add 2–3 more glasses daily." : "Hydration levels are optimal." },
            { name: "Nutrition",   risk: nr,           score: d.risks?.nutritionScore || 0, tip: nr === "High" ? "Poor nutritional tracking. Log all meals consistently." : nr === "Moderate" ? "Diet imbalance detected." : "Nutritional habits are on track." },
            { name: "Stress",      risk: sr,           score: Math.max(0, 100-(d.risks?.stressScore||0)), tip: sr === "High" ? "Elevated stress markers. Consider mindfulness." : sr === "Moderate" ? "Short breaks and breathing exercises help." : "Stress well-managed." },
            { name: "Sleep",       risk: sleepRisk,    score: sleepPct,  tip: sleepRisk === "High" ? "Poor sleep. Aim for 7–9 hours nightly." : sleepRisk === "Moderate" ? "Sleep duration below optimal." : "Sleep patterns are healthy." },
            { name: "Activity",    risk: activityRisk, score: activePct, tip: activityRisk === "High" ? "Sedentary lifestyle. Add 30 min exercise daily." : activityRisk === "Moderate" ? "Increase movement gradually." : "Activity levels are excellent." },
            { name: "Medication",  risk: medRisk,      score: medsTotal === 0 ? 0 : medPct, tip: medsTotal === 0 ? "No medication schedules found in the app." : medRisk === "High" ? `Only ${medPct}% compliance. Follow your prescribed schedule strictly.` : medRisk === "Moderate" ? "Some missed doses detected. Set daily reminders." : "Medication adherence is excellent." },
          ].map(r => `
            <div style="border-radius:12px;padding:12px;background:${riskBg(r.risk)};border:1.5px solid ${riskColor(r.risk)}44">
              <div style="font-size:8px;color:#64748B;text-transform:uppercase;font-weight:700;letter-spacing:0.4px;margin-bottom:4px">${r.name}</div>
              <div style="display:flex;align-items:center;gap:4px;margin:4px 0">
                <div style="width:7px;height:7px;border-radius:50%;background:${riskColor(r.risk)}"></div>
                <span style="font-size:12px;font-weight:800;color:${riskColor(r.risk)}">${r.risk}</span>
              </div>
              <div style="font-size:8px;color:#94A3B8;margin-bottom:5px">Score: ${r.score}/100</div>
              ${bar(r.score, riskColor(r.risk), 5)}
              <div style="font-size:8.5px;color:#475569;line-height:1.4;font-weight:500;margin-top:6px">${r.tip}</div>
            </div>`).join("")}
        </div>

        <!-- AI Prediction -->
        ${sectionTitle("AI Future Health Prediction", "Powered by Aorane AI", "#38BDF8")}
        <div style="display:flex;gap:10px">
          <div style="flex:1;background:linear-gradient(135deg,#1E293B,#0F1F38);border:1.5px solid #334155;border-radius:12px;padding:14px">
            <div style="font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:0.6px;color:#38BDF8;margin-bottom:10px">30-Day Forecast</div>
            ${[
              { m: "Health Score",    v: `${trend30Score}/100`, c: scoreColor(trend30Score) },
              { m: "Activity Status", v: "Maintaining",         c: "#10B981" },
              { m: "Hydration",       v: "On track",            c: "#0EA5E9" },
              { m: "Wellness Trend",  v: "Stable",              c: "#F59E0B" },
            ].map(r => `
              <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid rgba(255,255,255,0.06)">
                <span style="font-size:10px;color:#94A3B8;font-weight:600">${r.m}</span>
                <span style="font-size:10.5px;font-weight:800;color:${r.c}">${r.v}</span>
              </div>`).join("")}
          </div>
          <div style="flex:1;background:linear-gradient(135deg,#1A103A,#0F1A30);border:1.5px solid #4C1D95;border-radius:12px;padding:14px">
            <div style="font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:0.6px;color:#A78BFA;margin-bottom:10px">90-Day Forecast</div>
            ${[
              { m: "Health Score",    v: `${trend90Score}/100`,       c: scoreColor(trend90Score) },
              { m: "Activity Status", v: "Sustained Active",          c: "#10B981" },
              { m: "Nutrition",       v: "Well balanced",             c: "#F59E0B" },
              { m: "Wellness Trend",  v: "Intervention advised",      c: "#F97316" },
            ].map(r => `
              <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid rgba(255,255,255,0.06)">
                <span style="font-size:10px;color:#94A3B8;font-weight:600">${r.m}</span>
                <span style="font-size:10.5px;font-weight:800;color:${r.c}">${r.v}</span>
              </div>`).join("")}
          </div>
        </div>

        <!-- Future Risk cards -->
        <div style="display:flex;gap:8px">
          ${[
            { lbl: "Lifestyle Risk",  risk: lifestyleRisk, note: "Based on activity and score trend" },
            { lbl: "Weight Risk",     risk: weightRisk,    note: "Based on BMI and goal trajectory" },
            { lbl: "Activity Risk",   risk: activityRisk,  note: "Based on exercise consistency" },
            { lbl: "Wellness Risk",   risk: wellnessRisk,  note: "Based on overall health composite" },
          ].map(r => `
            <div style="flex:1;border-radius:10px;padding:10px;border:1.5px solid ${riskColor(r.risk)}44;background:${riskBg(r.risk)}">
              <div style="font-size:7.5px;color:#64748B;text-transform:uppercase;font-weight:700;margin-bottom:3px">${r.lbl}</div>
              <div style="font-size:14px;font-weight:900;color:${riskColor(r.risk)}">${r.risk}</div>
              <div style="font-size:8px;color:#94A3B8;margin-top:3px">${r.note}</div>
            </div>`).join("")}
        </div>

        <!-- AI Recommendations -->
        <div style="background:linear-gradient(135deg,#0F172A,#1A2744);border-radius:12px;padding:14px">
          <div style="font-size:11px;font-weight:800;color:#38BDF8;margin-bottom:8px">Personalized Recommendations</div>
          ${[
            activePct >= 70 ? "Maintain your activity level — consider adding strength training 2× weekly." : "Gradually increase daily movement — start with 15-minute walks.",
            Number(avgWater) >= 7 ? "Excellent hydration — continue tracking to maintain consistency." : `Increase water intake to 8 glasses/day. Currently averaging ${avgWater} glasses.`,
            allNutZero ? "Begin tracking meals in Aorane to receive personalized dietary guidance." : "Explore Aorane's meal planner for optimized nutrition targets.",
            sr !== "Low" ? "Practice 5-minute breathing exercises each morning to reduce cortisol." : "Sleep and stress metrics are on track — maintain your current routine.",
          ].map(tip => `
            <div style="display:flex;align-items:flex-start;gap:7px;padding:6px 0;border-bottom:1px solid rgba(255,255,255,0.06)">
              <div style="width:6px;height:6px;border-radius:50%;background:#38BDF8;flex-shrink:0;margin-top:4px"></div>
              <div style="font-size:10.5px;color:#CBD5E1;line-height:1.6">${tip}</div>
            </div>`).join("")}
        </div>
      </div>
    </div>

    ${pageFooter(d.reportId || "—", d.generatedAt, 3, TOTAL_PAGES, P)}
  </div>`;

  // ════════════════════════════════════════════════════════
  //  PAGE 4 — TREND ANALYTICS + SEASONAL + FLAGS + DISCLAIMER
  // ════════════════════════════════════════════════════════
  const exerciseValues = allLogs.map(l => l?.exerciseMinutes || 0);
  const waterValues    = allLogs.map(l => l?.waterGlasses    || 0);
  const sleepValues    = allLogs.map(l => (l as any)?.sleepHours || 0);

  const page4 = `
  <div class="page" id="page-4">
    <div class="watermark">AORANE HEALTH INTELLIGENCE REPORT</div>
    ${miniHeader("Trends · Seasonal · Alerts · Disclaimer", P, A, d.dateFrom, d.dateTo, periodLabel)}

    <div style="padding:14px 20px;flex:1;display:flex;flex-direction:column;gap:12px">

      <!-- Trend charts row -->
      ${sectionTitle("Health Trend Analytics", `${periodLabel} Data`, P)}
      <div style="display:flex;gap:12px">
        <div style="flex:1;background:#F8FAFC;border:1px solid #E8F0F8;border-radius:12px;padding:12px">
          <div style="font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:0.4px;color:#64748B;margin-bottom:8px">Water Intake (Glasses/Day)</div>
          ${barChart(waterValues, logDays, "#0EA5E9", 310, 72)}
        </div>
        <div style="flex:1;background:#F8FAFC;border:1px solid #E8F0F8;border-radius:12px;padding:12px">
          <div style="font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:0.4px;color:#64748B;margin-bottom:8px">Sleep (Hours/Night)</div>
          ${barChart(sleepValues, logDays, "#6366F1", 310, 72)}
        </div>
      </div>

      <div style="background:#F8FAFC;border:1px solid #E8F0F8;border-radius:12px;padding:12px">
        <div style="font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:0.4px;color:#64748B;margin-bottom:8px">Health Score Bar Chart — ${periodLabel}</div>
        ${barChart(logScores, logDays, scoreColor(avgScore), 660, 78)}
      </div>

      <!-- Weight maintenance -->
      <div style="background:linear-gradient(135deg,${P}08,${A}0A);border:1px solid ${P}22;border-radius:12px;padding:14px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
          <div>
            <div style="font-size:11.5px;font-weight:800;color:#0F172A">${d.goals?.goalType === "lose_weight" ? "Weight Loss Protocol" : d.goals?.goalType === "gain_weight" ? "Muscle & Weight Gain" : "Weight Maintenance"}</div>
            <div style="font-size:9px;color:#64748B;margin-top:2px">Daily target: ${d.goals?.targetCalories || 2000} kcal</div>
          </div>
          <div style="font-size:22px;font-weight:900;color:${P}">${d.goals?.goalType === "maintain" ? "100" : d.goals?.progressPercent || 0}%</div>
        </div>
        ${gradBar(d.goals?.goalType === "maintain" ? 100 : (d.goals?.progressPercent || 0), P, A, 10)}
        <div style="display:flex;gap:8px;margin-top:10px">
          ${[
            { lbl: "Current Weight", val: d.profile?.weight_kg ? `${d.profile.weight_kg} kg` : "—" },
            { lbl: "Target Weight",  val: d.goals?.targetWeight ? `${d.goals.targetWeight} kg` : "—" },
            { lbl: "BMI",            val: d.profile?.bmi || "—" },
            { lbl: "BMI Category",   val: d.profile?.bmiCategory || "—" },
            { lbl: "Trend",          val: d.goals?.weeklyTrend === "improving" ? "↗ Improving" : d.goals?.weeklyTrend === "stable" ? "→ Stable" : "↘ Declining" },
          ].map(s => `
            <div style="flex:1;background:#fff;border-radius:9px;padding:8px 7px;text-align:center;border:1px solid #E8F0F8">
              <div style="font-size:7px;color:#64748B;text-transform:uppercase;font-weight:700;margin-bottom:2px">${s.lbl}</div>
              <div style="font-size:11px;font-weight:900;color:${P}">${s.val}</div>
            </div>`).join("")}
        </div>
      </div>

      <!-- Seasonal + Flags side by side -->
      <div style="display:flex;gap:12px">

        <!-- Seasonal guidance -->
        <div style="flex:1;background:${guide.bg};border:1px solid ${guide.border};border-radius:12px;padding:14px">
          <div style="font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:0.5px;color:${guide.color};margin-bottom:10px">${guide.title}</div>
          <div style="font-size:8.5px;color:${guide.color}88;margin-bottom:9px">Personalized for ${d.weather?.city || d.profile?.city || "your region"}</div>
          ${guide.tips.map((tip: string, i: number) => `
            <div style="display:flex;align-items:flex-start;gap:9px;padding:7px 0;border-bottom:1px solid ${guide.border}">
              <div style="width:20px;height:20px;border-radius:50%;background:${guide.color}18;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:10px;font-weight:900;color:${guide.color}">${i+1}</div>
              <span style="font-size:10px;font-weight:500;color:${guide.color}CC;line-height:1.5">${tip}</span>
            </div>`).join("")}
        </div>

        <!-- Medical Flags + AI Insight -->
        <div style="flex:1;display:flex;flex-direction:column;gap:10px">
          <div>
            <div style="font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:0.5px;color:#DC2626;margin-bottom:8px;padding-bottom:6px;border-bottom:1.5px solid #F0F4F8">Medical Flags & Clinical Alerts</div>
            ${flags.map(f => `
              <div style="display:flex;gap:9px;align-items:flex-start;padding:9px 12px;border-radius:9px;border-left:4px solid ${fBorder[f.level]};background:${fBg[f.level]};margin-bottom:6px">
                <div>
                  <div style="font-size:10.5px;font-weight:800;color:${fColor[f.level]};margin-bottom:2px">${f.msg}</div>
                  <div style="font-size:9px;line-height:1.5;color:${fColor[f.level]}BB">${f.detail}</div>
                </div>
              </div>`).join("")}
          </div>

          <!-- QR + Report link -->
          <div style="background:#F8FAFC;border:1.5px solid #E8F0F8;border-radius:12px;padding:14px;display:flex;align-items:center;gap:14px">
            <div style="width:70px;height:70px;background:#F1F5F9;border:1.5px solid #E2E8F0;border-radius:10px;display:flex;align-items:center;justify-content:center;flex-shrink:0">
              <svg width="50" height="50" viewBox="0 0 50 50" xmlns="http://www.w3.org/2000/svg">
                <rect x="2" y="2" width="18" height="18" rx="2" fill="none" stroke="${P}" stroke-width="1.5"/>
                <rect x="6" y="6" width="10" height="10" fill="${P}" rx="1"/>
                <rect x="30" y="2" width="18" height="18" rx="2" fill="none" stroke="${P}" stroke-width="1.5"/>
                <rect x="34" y="6" width="10" height="10" fill="${P}" rx="1"/>
                <rect x="2" y="30" width="18" height="18" rx="2" fill="none" stroke="${P}" stroke-width="1.5"/>
                <rect x="6" y="34" width="10" height="10" fill="${P}" rx="1"/>
                <rect x="30" y="30" width="5" height="5" fill="${P}"/><rect x="38" y="30" width="5" height="5" fill="${P}"/>
                <rect x="30" y="38" width="5" height="5" fill="${P}"/><rect x="45" y="38" width="5" height="5" fill="${P}"/>
              </svg>
            </div>
            <div>
              <div style="font-size:12px;font-weight:800;color:#0F172A;margin-bottom:5px">View Interactive Health Report</div>
              <div style="font-size:9.5px;color:#64748B;line-height:1.6">Scan with the Aorane app to access real-time charts, full history, and personalized recommendations.</div>
              <div style="font-size:9px;font-weight:700;color:${P};margin-top:5px">aorane.health/report/${d.reportId || "your-report-id"}</div>
            </div>
          </div>
        </div>
      </div>

      <!-- Disclaimer -->
      <div style="background:#FFF7ED;border:1px solid #FED7AA;border-radius:10px;padding:12px 14px">
        <div style="font-size:10px;font-weight:800;color:#9A3412;margin-bottom:4px">Important Medical Disclaimer</div>
        <div style="font-size:8.5px;color:#7C2D12;line-height:1.7">
          This Aorane Health Intelligence Report is generated by AI algorithms based solely on self-reported data. It is intended exclusively for informational, educational, and personal wellness tracking purposes. This report does NOT constitute a medical diagnosis, clinical assessment, or professional medical advice. Always consult a qualified healthcare professional regarding any medical symptoms, conditions, medications, or treatment changes.
        </div>
      </div>
    </div>

    <!-- Final footer -->
    <div style="background:#F8FAFC;border-top:1px solid #E2E8F0;padding:10px 20px;display:flex;flex-direction:column;gap:4px;text-align:center;flex-shrink:0">
      <div style="display:flex;align-items:center;justify-content:center;gap:8px">
        ${logoImg(20)}
        <span style="font-size:12px;font-weight:900;color:${P}">AORANE HEALTH INTELLIGENCE REPORT</span>
      </div>
      <div style="font-size:8.5px;color:#94A3B8">
        Report ID: <strong style="color:#64748B">${d.reportId || "—"}</strong>
        &nbsp;·&nbsp; Generated: ${fmtDate(d.generatedAt)}
        &nbsp;·&nbsp; Period: ${fmtDate(d.dateFrom)} — ${fmtDate(d.dateTo)} (${periodDays} days)
      </div>
      <div style="font-size:8px;color:#CBD5E1">Powered by Aorane AI · Confidential · For Personal Use Only · Page 4 of ${TOTAL_PAGES}</div>
    </div>
  </div>`;

  // ── CSS ──────────────────────────────────────────────────
  const css = `
*{box-sizing:border-box;margin:0;padding:0;-webkit-print-color-adjust:exact;print-color-adjust:exact}
body{font-family:'Segoe UI',system-ui,Arial,Helvetica,sans-serif;background:#D8E8F5;padding:0}
.page{background:#fff;width:800px;margin:0 auto 0;position:relative;page-break-after:always;page-break-inside:avoid;display:flex;flex-direction:column;min-height:1050px}
.page:last-child{page-break-after:auto;margin-bottom:0}
.watermark{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%) rotate(-35deg);font-size:26px;font-weight:900;color:${P};opacity:0.018;letter-spacing:6px;white-space:nowrap;pointer-events:none;z-index:0;text-transform:uppercase}
.cover-hdr{background:linear-gradient(145deg,${P} 0%,${A} 60%,#0099c8 100%);padding:22px 24px 18px;position:relative;overflow:hidden;flex-shrink:0}
.cover-hdr::before{content:'';position:absolute;right:-80px;top:-80px;width:240px;height:240px;border-radius:50%;background:rgba(255,255,255,0.05)}
@media print{
  body{background:#fff;padding:0}
  .page{box-shadow:none;margin:0;border-radius:0}
}
`;

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=800"/>
<title>Aorane Health Intelligence Report — ${d.reportId || ""}</title>
<style>${css}</style>
</head>
<body>
${page1}
${page2}
${page3}
${page4}
</body>
</html>`;
}